package io.github.diodeme.ji.session.model;

import java.util.Objects;

/** Rejects late effect completions before they can mutate canonical state. */
public final class CompletionGuard {
    private CompletionGuard() {}

    public static void requireCurrent(OperationIdentity expected, OperationIdentity completion) {
        Objects.requireNonNull(expected, "expected");
        Objects.requireNonNull(completion, "completion");
        if (!expected.equals(completion)) {
            throw new StaleCompletionException(expected, completion);
        }
    }

    public record OperationIdentity(String operationId, long revision) {
        public OperationIdentity {
            if (operationId == null || operationId.isBlank()) {
                throw new IllegalArgumentException("operationId must not be blank");
            }
            if (revision < 0) {
                throw new IllegalArgumentException("revision must be non-negative");
            }
        }
    }

    public static final class StaleCompletionException extends IllegalStateException {
        private static final long serialVersionUID = 1L;

        public StaleCompletionException(OperationIdentity expected, OperationIdentity completion) {
            super("stale completion for " + completion.operationId()
                    + ": expected revision " + expected.revision()
                    + ", got " + completion.revision());
        }
    }
}
